function tooltip(options) {
  let el;
  const instance = createTooltipInstance();
  createEffect(
    () => options.content,
    content => el && instance.setContent(content)
  );
  onCleanup(() => instance.destroy());

  return nextEl => {
    el = nextEl;
    instance.attach(nextEl);
  };
}

<button ref={tooltip({ content: "Save" })} />;

